sp_widget.css:
.recent-card{

background:white;

border-radius:28px;

padding:36px;

}

.header{

display:flex;

justify-content:space-between;

align-items:center;

margin-bottom:30px;

}

.header h2{

margin:0;

font-size:42px;

font-weight:900;

color:#07195A;

}

.badge{

width:58px;

height:58px;

border-radius:20px;

background:#EEF4FF;

display:flex;

align-items:center;

justify-content:center;

font-weight:900;

font-size:22px;

color:#2F62F5;

}

.employee-row{

display:flex;

align-items:center;

padding:20px;

border-radius:20px;

background:#F7F9FD;

margin-bottom:16px;

}

.avatar{

width:64px;

height:64px;

border-radius:22px;

background:
linear-gradient(
135deg,
#2F62F5,
#4C84FF
);

color:white;

font-size:28px;

font-weight:900;

display:flex;

align-items:center;

justify-content:center;

}

.employee-info{

margin-left:18px;

flex:1;

}

.emp-name{

font-size:22px;

font-weight:800;

color:#07195A;

}

.emp-role{

color:#65749A;

margin-top:4px;

}

.join-date{

margin-top:8px;

color:#98A5C5;

font-size:14px;

}

.view-btn{

display:inline-flex;

align-items:center;

justify-content:center;

min-width:160px;

height:60px;

padding:0 28px;

background:#2F62F5;

border-radius:18px;

color:white !important;

font-weight:800;

text-decoration:none !important;

cursor:pointer;

transition:.25s;

}

.view-btn:hover{

transform:translateY(-2px);

background:#1E4FE0;

box-shadow:
0 14px 28px rgba(47,98,245,.25);

}
.employee-row:last-child{

margin-bottom:0;

}

sp_widget.script:
(function(){

data.employees=[];
data.total=0;

var gr=
new GlideRecord(
'x_1902481_employ_0_employee'
);

gr.orderByDesc(
'join_date'
);

gr.setLimit(5);

gr.query();

while(gr.next()){

var empName=
gr.getDisplayValue()||
'Employee';

var joinDate=
gr.join_date?
gr.join_date.getDisplayValue():'Not available';

var designation=
gr.designation?gr.designation.getDisplayValue():'-';

data.total++;

data.employees.push({

sys_id:
gr.getUniqueValue(),

name:
empName,

designation:
designation,

join_date:
joinDate,

initial:
empName.charAt(0)

});

}

})();
